import { setup, assign, enqueueActions } from 'xstate';
import { toolCall } from '@astral-mcp/tools';

export default setup({}).createMachine({
  id: 'addStaleLabels',
  context: () => ({
    owner: 'acme',
    repo: 'widgets',
    cutoffDate: new Date('2026-07-01T00:00:00Z').getTime(),
    issues: [],
    staleIssues: [],
    updateResults: {},
  }),
  initial: 'fetchingIssues',
  states: {
    fetchingIssues: {
      entry: toolCall('github.list_issues', () => ({
        owner: 'acme',
        repo: 'widgets',
        state: 'OPEN',
        perPage: 100,
      }), { id: 'fetch1' }),
      on: {
        TOOL_RESULT: {
          actions: assign(({ event }) => {
            const result = typeof event.result === 'string' 
              ? JSON.parse(event.result)
              : event.result;
            const issues = result?.issues || [];

            const staleIssues = issues.filter(issue => {
              const updatedAt = new Date(issue.updated_at).getTime();
              return updatedAt < 1719792000000; // 2026-07-01T00:00:00Z
            });

            return {
              issues,
              staleIssues,
            };
          }),
          target: 'updatingIssues',
        },
        TOOL_ERROR: { target: 'failed' },
      },
    },
    updatingIssues: {
      entry: enqueueActions(({ context, enqueue }) => {
        context.staleIssues.forEach((issue, idx) => {
          const currentLabels = Array.isArray(issue.labels)
            ? issue.labels.map(l => typeof l === 'string' ? l : l.name)
            : [];

          const newLabels = [...new Set([...currentLabels, 'stale'])];

          enqueue(toolCall('github.issue_write', {
            method: 'update',
            owner: 'acme',
            repo: 'widgets',
            issue_number: issue.number,
            labels: newLabels,
          }, { id: 'u' + idx }));
        });
      }),
      on: {
        TOOL_RESULT: {
          actions: assign(({ context, event }) => ({
            updateResults: { 
              ...context.updateResults, 
              [event.callId]: { status: 'success' } 
            },
          })),
        },
        TOOL_DENIED: {
          actions: assign(({ context, event }) => ({
            updateResults: { 
              ...context.updateResults, 
              [event.callId]: { status: 'denied', reason: event.reason } 
            },
          })),
        },
        TOOL_ERROR: {
          actions: assign(({ context, event }) => ({
            updateResults: { 
              ...context.updateResults, 
              [event.callId]: { status: 'error', error: event.error } 
            },
          })),
        },
      },
      always: {
        guard: ({ context }) => {
          const resultCount = Object.keys(context.updateResults).length;
          return resultCount === context.staleIssues.length;
        },
        target: 'done',
      },
    },
    done: { type: 'final' },
    failed: { type: 'final' },
  },
  output: ({ context }) => {
    const results = Object.values(context.updateResults);
    return {
      totalIssuesChecked: context.issues.length,
      staleIssuesFound: context.staleIssues.length,
      successfulUpdates: results.filter(r => r.status === 'success').length,
      skippedUpdates: results.filter(r => r.status === 'denied').length,
      failedUpdates: results.filter(r => r.status === 'error').length,
      staleIssuesList: context.staleIssues.map(i => ({
        number: i.number,
        title: i.title,
        updatedAt: i.updated_at,
      })),
    };
  },
});

