import { setup, assign, enqueueActions } from 'xstate';
import { toolCall } from '@astral-mcp/tools';

export default setup({}).createMachine({
  id: 'addStaleLabels',
  context: () => ({
    owner: 'acme',
    repo: 'widgets',
    cutoffDate: '2026-07-01T00:00:00Z',
    allIssues: [],
    staleLabelIssues: [],
    updatedIssues: [],
    skippedIssues: [],
    failedIssues: [],
    pageAfter: null,
    hasNextPage: true,
  }),
  initial: 'fetchingIssues',
  states: {
    fetchingIssues: {
      entry: toolCall('github.list_issues', ({ context }) => ({
        owner: context.owner,
        repo: context.repo,
        state: 'OPEN',
        perPage: 100,
        fields: ['number', 'title', 'labels', 'updated_at'],
        after: context.pageAfter,
      }), { id: 'fetchIssues' }),
      on: {
        TOOL_RESULT: {
          actions: assign(({ event, context }) => {
            const result = event.result;
            const issues = Array.isArray(result?.issues) ? result.issues : [];
            const newAllIssues = [...context.allIssues, ...issues];

            const pageInfo = result?.pageInfo || {};
            const hasNextPage = pageInfo.hasNextPage || false;
            const pageAfter = hasNextPage ? pageInfo.endCursor : null;

            return {
              allIssues: newAllIssues,
              hasNextPage,
              pageAfter,
            };
          }),
          target: 'checkNextPage',
        },
        TOOL_ERROR: { target: 'failed' },
      },
    },
    checkNextPage: {
      always: [
        {
          guard: ({ context }) => context.hasNextPage,
          target: 'fetchingIssues',
        },
        {
          target: 'filterStaleIssues',
        },
      ],
    },
    filterStaleIssues: {
      always: {
        actions: assign(({ context }) => {
          const cutoffDate = new Date(context.cutoffDate);
          const staleIssues = context.allIssues.filter(issue => {
            const updatedAt = new Date(issue.updated_at);
            return updatedAt < cutoffDate;
          });
          return {
            staleLabelIssues: staleIssues,
          };
        }),
        target: 'updatingIssues',
      },
    },
    updatingIssues: {
      entry: enqueueActions(({ context, enqueue }) => {
        context.staleLabelIssues.forEach((issue, index) => {
          const currentLabels = Array.isArray(issue.labels)
            ? issue.labels.map(l => typeof l === 'string' ? l : l.name || l)
            : [];

          const newLabels = [...currentLabels, 'stale'];
          const uniqueLabels = [...new Set(newLabels)];

          enqueue(toolCall('github.issue_write', {
            method: 'update',
            owner: context.owner,
            repo: context.repo,
            issue_number: issue.number,
            labels: uniqueLabels,
          }, { id: 'update' + index }));
        });
      }),
      on: {
        TOOL_RESULT: {
          actions: assign(({ context, event }) => ({
            updatedIssues: [...context.updatedIssues, event.callId],
          })),
        },
        TOOL_DENIED: {
          actions: assign(({ context, event }) => ({
            skippedIssues: [...context.skippedIssues, event.callId],
          })),
        },
        TOOL_ERROR: {
          actions: assign(({ context, event }) => ({
            failedIssues: [...context.failedIssues, event.callId],
          })),
        },
      },
      always: {
        guard: ({ context }) => {
          const totalResponses = context.updatedIssues.length + 
                                 context.skippedIssues.length + 
                                 context.failedIssues.length;
          return totalResponses === context.staleLabelIssues.length;
        },
        target: 'done',
      },
    },
    done: { type: 'final' },
    failed: { type: 'final' },
  },
  output: ({ context }) => ({
    totalIssuesChecked: context.allIssues.length,
    staleIssuesFound: context.staleLabelIssues.length,
    successfulUpdates: context.updatedIssues.length,
    skippedUpdates: context.skippedIssues.length,
    failedUpdates: context.failedIssues.length,
    details: {
      staleIssues: context.staleLabelIssues.map(i => ({
        number: i.number,
        title: i.title,
        updatedAt: i.updated_at,
      })),
    },
  }),
});

