import { setup, assign, enqueueActions } from 'xstate';
import { toolCall, whenCall } from '@astral-mcp/tools';

export default setup({}).createMachine({
  id: 'commentOnPRs',
  context: {
    owner: 'acme',
    repo: 'widgets',
    prs: [],
    prsToComment: [],
    filesChecked: {},
    commented: [],
    failed: [],
    skipped: [],
  },
  initial: 'listPRs',
  states: {
    listPRs: {
      entry: toolCall('github.list_pull_requests', ({ context }) => ({
        owner: context.owner,
        repo: context.repo,
        state: 'open',
        fields: ['number', 'title'],
      })),
      on: {
        TOOL_RESULT: {
          target: 'checkFiles',
          actions: assign({
            prs: ({ event }) => {
              // Handle both array and object responses
              if (Array.isArray(event.result)) {
                return event.result;
              } else if (event.result && typeof event.result === 'object' && Array.isArray(event.result.pullRequests)) {
                return event.result.pullRequests;
              }
              return [];
            },
          }),
        },
        TOOL_ERROR: 'done',
      },
    },
    checkFiles: {
      entry: enqueueActions(({ context, enqueue }) => {
        context.prs.forEach((pr) => {
          enqueue(toolCall('github.pull_request_read', {
            owner: context.owner,
            repo: context.repo,
            pullNumber: pr.number,
            method: 'get_files',
            perPage: 100,
          }, { id: `check_${pr.number}` }));
        });
      }),
      on: {
        TOOL_RESULT: {
          actions: assign({
            filesChecked: ({ context, event }) => {
              const callId = event.callId;
              const prNumber = parseInt(callId.replace('check_', ''));
              const files = event.result;
              const hasExportFiles = Array.isArray(files) 
                ? files.some(f => f.filename && f.filename.startsWith('src/export/'))
                : files && typeof files === 'object' && files.files 
                  ? files.files.some(f => f.filename && f.filename.startsWith('src/export/'))
                  : false;

              return {
                ...context.filesChecked,
                [prNumber]: hasExportFiles,
              };
            },
            prsToComment: ({ context, event }) => {
              const callId = event.callId;
              const prNumber = parseInt(callId.replace('check_', ''));
              const files = event.result;
              const hasExportFiles = Array.isArray(files)
                ? files.some(f => f.filename && f.filename.startsWith('src/export/'))
                : files && typeof files === 'object' && files.files
                  ? files.files.some(f => f.filename && f.filename.startsWith('src/export/'))
                  : false;

              if (hasExportFiles) {
                return [...context.prsToComment, prNumber];
              }
              return context.prsToComment;
            },
          }),
        },
        TOOL_ERROR: 'done',
      },
      always: {
        guard: ({ context }) => {
          const checkedCount = Object.keys(context.filesChecked).length;
          return checkedCount === context.prs.length;
        },
        target: 'addComments',
      },
    },
    addComments: {
      entry: enqueueActions(({ context, enqueue }) => {
        context.prsToComment.forEach((prNumber) => {
          enqueue(toolCall('github.add_issue_comment', {
            owner: context.owner,
            repo: context.repo,
            issue_number: prNumber,
            body: 'Please add a CHANGELOG entry for the export changes.',
          }, { id: `comment_${prNumber}` }));
        });
      }),
      on: {
        TOOL_RESULT: {
          actions: assign({
            commented: ({ context, event }) => [...context.commented, event.callId],
          }),
        },
        TOOL_DENIED: {
          actions: assign({
            skipped: ({ context, event }) => [...context.skipped, event.callId],
          }),
        },
        TOOL_ERROR: {
          actions: assign({
            failed: ({ context, event }) => [...context.failed, event.callId],
          }),
        },
      },
      always: {
        guard: ({ context }) => {
          const totalComments = context.commented.length + context.skipped.length + context.failed.length;
          return totalComments === context.prsToComment.length;
        },
        target: 'done',
      },
    },
    done: {
      type: 'final',
    },
  },
  output: ({ context }) => ({
    totalPRsChecked: context.prs.length,
    prsWithExportChanges: context.prsToComment.length,
    commented: context.commented.length,
    skipped: context.skipped.length,
    failed: context.failed.length,
  }),
});

