import { toolCall, whenCall } from '@astral-mcp/tools';

export default setup({}).createMachine({
  id: 'commentOnPRs',
  context: {
    owner: 'acme',
    repo: 'widgets',
    prs: [],
    prsToComment: [],
    filesChecked: 0,
    commented: [],
    failed: [],
    skipped: [],
  },
  initial: 'listPRs',
  states: {
    listPRs: {
      entry: toolCall('github.list_pull_requests', ({ context }) => ({
        owner: context.owner,
        repo: context.repo,
        state: 'open',
      })),
      on: {
        TOOL_RESULT: {
          target: 'checkFiles',
          actions: assign({
            prs: ({ event }) => {
              // Handle array response
              const result = event.result;
              if (Array.isArray(result)) {
                return result;
              }
              return [];
            },
          }),
        },
        TOOL_ERROR: {
          target: 'done',
          actions: assign({
            failed: [{ error: 'Failed to list PRs' }],
          }),
        },
      },
    },
    checkFiles: {
      entry: enqueueActions(({ context, enqueue }) => {
        context.prs.forEach((pr, idx) => {
          enqueue(toolCall('github.pull_request_read', {
            owner: context.owner,
            repo: context.repo,
            pullNumber: pr.number,
            method: 'get_files',
            perPage: 100,
          }, { id: `check_${idx}` }));
        });
      }),
      on: {
        TOOL_RESULT: {
          actions: assign({
            filesChecked: ({ context, event }) => context.filesChecked + 1,
            prsToComment: ({ context, event }) => {
              const files = event.result;
              const callId = event.callId;
              const idx = parseInt(callId.replace('check_', ''));
              const pr = context.prs[idx];

              // Check if any file is under src/export/
              const hasExportFiles = Array.isArray(files)
                ? files.some(f => f.filename && f.filename.startsWith('src/export/'))
                : false;

              if (hasExportFiles) {
                return [...context.prsToComment, pr.number];
              }
              return context.prsToComment;
            },
          }),
        },
        TOOL_ERROR: {
          actions: assign({
            failed: ({ context, event }) => [...context.failed, event.callId],
          }),
        },
      },
      always: {
        guard: ({ context }) => context.filesChecked === context.prs.length,
        target: 'addComments',
      },
    },
    addComments: {
      entry: enqueueActions(({ context, enqueue }) => {
        context.prsToComment.forEach((prNumber, idx) => {
          enqueue(toolCall('github.add_issue_comment', {
            owner: context.owner,
            repo: context.repo,
            issue_number: prNumber,
            body: 'Please add a CHANGELOG entry for the export changes.',
          }, { id: `comment_${idx}` }));
        });
      }),
      on: {
        TOOL_RESULT: {
          actions: assign({
            commented: ({ context, event }) => [...context.commented, event.callId],
          }),
        },
        TOOL_DENIED: {
          actions: assign({
            skipped: ({ context, event }) => [...context.skipped, event.callId],
          }),
        },
        TOOL_ERROR: {
          actions: assign({
            failed: ({ context, event }) => [...context.failed, event.callId],
          }),
        },
      },
      always: {
        guard: ({ context }) => {
          const totalResults = context.commented.length + context.skipped.length + context.failed.length;
          return totalResults === context.prsToComment.length;
        },
        target: 'done',
      },
    },
    done: {
      type: 'final',
    },
  },
  output: ({ context }) => ({
    totalPRsChecked: context.prs.length,
    prsWithExportChanges: context.prsToComment.length,
    prsToCommentList: context.prsToComment,
    commentedCount: context.commented.length,
    skippedCount: context.skipped.length,
    failedCount: context.failed.length,
  }),
});

