      entry: enqueueActions(({ context, enqueue }) => {
        context.prs.forEach((pr, idx) => {
          enqueue(toolCall('github.pull_request_read', {
            owner: context.owner,
            repo: context.repo,
            pullNumber: pr.number,
            method: 'get_files',
            perPage: 100,
          }, { id: `check_${idx}` }));
        });
      }),
      on: {
        TOOL_RESULT: {
          actions: assign({
            filesChecked: ({ context }) => context.filesChecked + 1,
            prsToComment: ({ context, event }) => {
              const callId = event.callId;
              const idx = parseInt(callId.replace('check_', ''));
              const pr = context.prs[idx];

              // Parse result if it's a string
              let files;
              try {
                files = typeof event.result === 'string' ? JSON.parse(event.result) : event.result;
              } catch {
                files = [];
              }

              // Check if any file is under src/export/
              const hasExportFiles = Array.isArray(files)
                ? files.some(f => f.filename && f.filename.startsWith('src/export/'))
                : false;

              if (hasExportFiles) {
                return [...context.prsToComment, pr.number];
              }
              return context.prsToComment;
            },
          }),
        },
        TOOL_ERROR: {
          actions: assign({
            failed: ({ context, event }) => [...context.failed, event.callId],
          }),
        },
      },
      always: {
        guard: ({ context }) => context.filesChecked === context.prs.length,
        target: 'addComments',
      },
    },
    addComments: {
      entry: enqueueActions(({ context, enqueue }) => {
        context.prsToComment.forEach((prNumber, idx) => {
          enqueue(toolCall('github.add_issue_comment', {
            owner: context.owner,
            repo: context.repo,
            issue_number: prNumber,
            body: 'Please add a CHANGELOG entry for the export changes.',
          }, { id: `comment_${idx}` }));
        });
      }),
      on: {
        TOOL_RESULT: {
          actions: assign({
            commented: ({ context, event }) => [...context.commented, event.callId],
          }),
        },
        TOOL_DENIED: {
          actions: assign({
            skipped: ({ context, event }) => [...context.skipped, event.callId],
          }),
        },
        TOOL_ERROR: {
          actions: assign({
            failed: ({ context, event }) => [...context.failed, event.callId],
          }),
        },
      },
      always: {
        guard: ({ context }) => {
          const totalResults = context.commented.length + context.skipped.length + context.failed.length;
          return totalResults === context.prsToComment.length;
        },
        target: 'done',
      },
    },
    done: {
      type: 'final',
    },
  },
  output: ({ context }) => ({
    totalPRsChecked: context.prs.length,
    prsWithExportChanges: context.prsToComment.length,
    prsToCommentList: context.prsToComment,
    commentedCount: context.commented.length,
    skippedCount: context.skipped.length,
    failedCount: context.failed.length,
  }),
});

import { setup, assign, enqueueActions } from 'xstate';
import { toolCall, whenCall } from '@astral-mcp/tools';

export default setup({}).createMachine({
  id: 'auditLogMachine',
  context: {
    shippedOrders: [],
    existingAuditLogs: [],
    missingAuditLogs: [],
    insertResult: null,
    errorMessage: null,
  },
  initial: 'findShippedOrders',
  states: {
    findShippedOrders: {
      entry: toolCall('mongo.find', {
        connectionId: 'preconfigured',
        database: 'shop',
        collection: 'orders',
        filter: { status: 'shipped' },
        projection: { orderId: 1 },
      }, { id: 'findShipped' }),
      on: {
        TOOL_RESULT: {
          guard: whenCall('findShipped'),
          target: 'findExistingAuditLogs',
          actions: assign({ shippedOrders: ({ event }) => event.result.documents || [] }),
        },
        TOOL_ERROR: {
          target: 'failed',
          actions: assign({ errorMessage: ({ event }) => `Error finding shipped orders: ${event.error}` }),
        },
      },
    },
    findExistingAuditLogs: {
      entry: toolCall('mongo.find', {
        connectionId: 'preconfigured',
        database: 'shop',
        collection: 'audit_log',
        filter: { action: 'shipped' },
        projection: { orderId: 1 },
      }, { id: 'findAudit' }),
      on: {
        TOOL_RESULT: {
          guard: whenCall('findAudit'),
          target: 'identifyMissing',
          actions: assign({ existingAuditLogs: ({ event }) => event.result.documents || [] }),
        },
        TOOL_ERROR: {
          target: 'failed',
          actions: assign({ errorMessage: ({ event }) => `Error finding audit logs: ${event.error}` }),
        },
      },
    },
    identifyMissing: {
      entry: assign({
        missingAuditLogs: ({ context }) => {
          const existingOrderIds = new Set(
            context.existingAuditLogs.map(log => log.orderId)
          );
          return context.shippedOrders
            .filter(order => !existingOrderIds.has(order.orderId))
            .map(order => ({
              orderId: order.orderId,
              action: 'shipped',
            }));
        },
      }),
      always: {
        target: 'insertIfNeeded',
      },
    },
    insertIfNeeded: {
      always: [
        {
          guard: ({ context }) => context.missingAuditLogs.length === 0,
          target: 'done',
        },
        {
          target: 'insertAuditLogs',
        },
      ],
    },
    insertAuditLogs: {
      entry: toolCall('mongo.insert-many', {
        connectionId: 'preconfigured',
        database: 'shop',
        collection: 'audit_log',
        documents: ({ context }) => context.missingAuditLogs,
      }, { id: 'insertAudit' }),
      on: {
        TOOL_RESULT: {
          guard: whenCall('insertAudit'),
          target: 'done',
          actions: assign({ insertResult: ({ event }) => event.result }),
        },
        TOOL_DENIED: {
          target: 'done',
          actions: assign({ errorMessage: 'User denied the insert operation' }),
        },
        TOOL_ERROR: {
          target: 'failed',
          actions: assign({ errorMessage: ({ event }) => `Error inserting audit logs: ${event.error}` }),
        },
      },
    },
    done: {
      type: 'final',
    },
    failed: {
      type: 'final',
    },
  },
  output: ({ context }) => ({
    shippedOrdersCount: context.shippedOrders.length,
    existingAuditLogsCount: context.existingAuditLogs.length,
    missingAuditLogsCount: context.missingAuditLogs.length,
    insertedCount: context.insertResult?.insertedCount || 0,
    errorMessage: context.errorMessage,
  }),
});

