import { setup, assign, enqueueActions } from 'xstate';
import { toolCall, whenCall } from '@astral-mcp/tools';

export default setup({}).createMachine({
  id: 'auditLogMachine',
  context: {
    shippedOrders: [],
    existingAuditLogs: [],
    missingAuditLogs: [],
    insertResult: null,
    errorMessage: null,
  },
  initial: 'findShippedOrders',
  states: {
    findShippedOrders: {
      entry: toolCall('mongo.find', {
        connectionId: 'preconfigured',
        database: 'shop',
        collection: 'orders',
        filter: { status: 'shipped' },
        limit: 1000,
      }, { id: 'findShipped' }),
      on: {
        TOOL_RESULT: {
          guard: whenCall('findShipped'),
          target: 'findExistingAuditLogs',
          actions: assign({ shippedOrders: ({ event }) => event.result.documents || [] }),
        },
        TOOL_ERROR: {
          target: 'failed',
          actions: assign({ errorMessage: ({ event }) => `Error finding shipped orders: ${event.error}` }),
        },
      },
    },
    findExistingAuditLogs: {
      entry: toolCall('mongo.find', {
        connectionId: 'preconfigured',
        database: 'shop',
        collection: 'audit_log',
        filter: { action: 'shipped' },
        limit: 1000,
      }, { id: 'findAudit' }),
      on: {
        TOOL_RESULT: {
          guard: whenCall('findAudit'),
          target: 'identifyMissing',
          actions: assign({ existingAuditLogs: ({ event }) => event.result.documents || [] }),
        },
        TOOL_ERROR: {
          target: 'failed',
          actions: assign({ errorMessage: ({ event }) => `Error finding audit logs: ${event.error}` }),
        },
      },
    },
    identifyMissing: {
      entry: assign({
        missingAuditLogs: ({ context }) => {
          const existingOrderIds = new Set(
            context.existingAuditLogs.map(log => log.orderId)
          );
          return context.shippedOrders
            .filter(order => !existingOrderIds.has(order.orderId))
            .map(order => ({
              orderId: order.orderId,
              action: 'shipped',
            }));
        },
      }),
      always: {
        target: 'insertIfNeeded',
      },
    },
    insertIfNeeded: {
      always: [
        {
          guard: ({ context }) => context.missingAuditLogs.length === 0,
          target: 'done',
        },
        {
          target: 'insertAuditLogs',
        },
      ],
    },
    insertAuditLogs: {
      entry: toolCall('mongo.insert-many', {
        connectionId: 'preconfigured',
        database: 'shop',
        collection: 'audit_log',
        documents: ({ context }) => context.missingAuditLogs,
      }, { id: 'insertAudit' }),
      on: {
        TOOL_RESULT: {
          guard: whenCall('insertAudit'),
          target: 'done',
          actions: assign({ insertResult: ({ event }) => event.result }),
        },
        TOOL_DENIED: {
          target: 'done',
          actions: assign({ errorMessage: 'User denied the insert operation' }),
        },
        TOOL_ERROR: {
          target: 'done',
          actions: assign({ errorMessage: ({ event }) => `Error inserting audit logs: ${event.error}` }),
        },
      },
    },
    done: {
      type: 'final',
    },
    failed: {
      type: 'final',
    },
  },
  output: ({ context }) => ({
    shippedOrdersCount: context.shippedOrders.length,
    existingAuditLogsCount: context.existingAuditLogs.length,
    missingAuditLogsCount: context.missingAuditLogs.length,
    missingOrderIds: context.missingAuditLogs.map(log => log.orderId),
    insertedCount: context.insertResult?.insertedCount || 0,
    insertedIds: context.insertResult?.insertedIds || [],
    errorMessage: context.errorMessage,
  }),
});

