import { setup, assign, enqueueActions } from 'xstate';
import { toolCall, whenCall } from '@astral-mcp/tools';

export default setup({}).createMachine({
  id: 'checkFailingFiles',
  context: {
    checkRuns: [],
    failingFiles: [],
    filesToCheck: [],
    fileCheckResults: {},
    issuesToCreate: [],
    commentsToCreate: [],
    processedCount: 0,
  },
  initial: 'getCheckRuns',
  states: {
    getCheckRuns: {
      entry: toolCall('github.pull_request_read', {
        owner: 'acme',
        repo: 'widgets',
        pullNumber: 139,
        method: 'get_check_runs',
      }),
      on: {
        TOOL_RESULT: {
          target: 'extractFailingFiles',
          actions: assign({ checkRuns: ({ event }) => event.result || [] }),
        },
        TOOL_ERROR: {
          target: 'error',
          actions: assign({ error: ({ event }) => event.error }),
        },
      },
    },

    extractFailingFiles: {
      entry: assign({
        failingFiles: ({ context }) => {
          const failing = [];
          if (Array.isArray(context.checkRuns)) {
            context.checkRuns.forEach((run) => {
              if (run.conclusion === 'failure' && run.output?.title) {
                failing.push({
                  checkName: run.name,
                  file: run.output.title,
                });
              }
            });
          }
          return failing;
        },
        filesToCheck: ({ context }) => {
          const files = [];
          if (Array.isArray(context.checkRuns)) {
            context.checkRuns.forEach((run) => {
              if (run.conclusion === 'failure' && run.output?.title) {
                files.push(run.output.title);
              }
            });
          }
          return files;
        },
      }),
      always: {
        target: 'checkFilesExist',
      },
    },

    checkFilesExist: {
      entry: enqueueActions(({ context, enqueue }) => {
        context.filesToCheck.forEach((file, i) => {
          enqueue(
            toolCall(
              'fs.get_file_info',
              { path: file },
              { id: `check_${i}` }
            )
          );
        });
      }),
      on: {
        TOOL_RESULT: {
          actions: assign({
            fileCheckResults: ({ context, event }) => ({
              ...context.fileCheckResults,
              [event.callId]: { exists: true, result: event.result },
            }),
