        method: 'get_check_runs',
      }),
      on: {
        TOOL_RESULT: {
          target: 'done',
          actions: assign({ 
            testResult: ({ event }) => {
              const data = event.result;
              if (data && data.check_runs && Array.isArray(data.check_runs)) {
                const failing = data.check_runs.filter(run => run.conclusion === 'failure');
                return {
                  totalRuns: data.check_runs.length,
                  failingCount: failing.length,
                  firstFailing: failing[0] || null,
                };
              }
              return null;
            },
          }),
        },
        TOOL_ERROR: {
          target: 'done',
          actions: assign({ testResult: ({ event }) => ({ error: event.error }) }),
        },
      },
    },
    done: { type: 'final' },
  },
  output: ({ context }) => context.testResult,
});

