});

import { setup, assign, enqueueActions } from 'xstate';
import { toolCall } from '@astral-mcp/tools';

export default setup({}).createMachine({
  id: 'checkFailingFiles',
  context: {
    checkRuns: [],
    failingFiles: [],
    filesToCheck: [],
    fileCheckResults: {},
    issuesToCreate: [],
    commentsToCreate: [],
    processedCount: 0,
  },
  initial: 'getCheckRuns',
  states: {
    getCheckRuns: {
      entry: toolCall('github.pull_request_read', {
        owner: 'acme',
        repo: 'widgets',
        pullNumber: 139,
        method: 'get_check_runs',
      }),
      on: {
        TOOL_RESULT: {
          target: 'extractFailingFiles',
          actions: assign({ 
            checkRuns: ({ event }) => {
              try {
                const data = typeof event.result === 'string' ? JSON.parse(event.result) : event.result;
                return data?.check_runs || [];
              } catch {
                return [];
              }
            },
          }),
        },
        TOOL_ERROR: {
          target: 'error',
          actions: assign({ error: ({ event }) => event.error }),
        },
      },
    },

    extractFailingFiles: {
      entry: assign({
        failingFiles: ({ context }) => {
          const failing = [];
          const seen = new Set();

          context.checkRuns.forEach((run) => {
            if (run.conclusion === 'failure' && run.output?.summary) {
              const summary = run.output.summary;

              // Try different patterns to extract file path
              let file = null;

              // Pattern: "in src/..." or "in docs/..."
              let match = summary.match(/in\s+([^\s:]+)/);
              if (match) {
                file = match[1];
              }

              // Pattern: "src/api/routes.ts:42:7"
              if (!file) {
                match = summary.match(/^([^\s:]+\.ts|[^\s:]+\.tsx|[^\s:]+\.md|[^\s:]+\.sh)/);
                if (match) {
                  file = match[1];
                }
              }

              if (file && !seen.has(file)) {
                seen.add(file);
                failing.push({
                  checkName: run.name,
                  file: file,
                });
              }
            }
          });
          return failing;
        },
        filesToCheck: ({ context }) => {
          const files = [];
          const seen = new Set();

          context.checkRuns.forEach((run) => {
            if (run.conclusion === 'failure' && run.output?.summary) {
              const summary = run.output.summary;

              // Try different patterns to extract file path
              let file = null;

              // Pattern: "in src/..." or "in docs/..."
              let match = summary.match(/in\s+([^\s:]+)/);
              if (match) {
                file = match[1];
              }

              // Pattern: "src/api/routes.ts:42:7"
              if (!file) {
                match = summary.match(/^([^\s:]+\.ts|[^\s:]+\.tsx|[^\s:]+\.md|[^\s:]+\.sh)/);
                if (match) {
                  file = match[1];
                }
              }

              if (file && !seen.has(file)) {
                seen.add(file);
                files.push(file);
              }
            }
          });
          return files;
        },
      }),
      always: {
        target: 'checkFilesExist',
      },
    },

    checkFilesExist: {
      entry: enqueueActions(({ context, enqueue }) => {
        context.filesToCheck.forEach((file, i) => {
          enqueue(
            toolCall(
              'fs.get_file_info',
              { path: file },
              { id: `check_${i}` }
            )
          );
        });
      }),
      on: {
        TOOL_RESULT: {
          actions: assign({
            fileCheckResults: ({ context, event }) => ({
              ...context.fileCheckResults,
              [event.callId]: { exists: true, result: event.result },
            }),
          }),
        },
        TOOL_ERROR: {
          actions: assign({
            fileCheckResults: ({ context, event }) => ({
              ...context.fileCheckResults,
              [event.callId]: { exists: false, error: event.error },
            }),
          }),
        },
      },
      always: {
        guard: ({ context }) =>
          Object.keys(context.fileCheckResults).length === context.filesToCheck.length,
        target: 'categorizeFiles',
      },
    },

    categorizeFiles: {
      entry: assign({
        issuesToCreate: ({ context }) => {
          const issues = [];
          context.failingFiles.forEach((item, i) => {
            const checkId = `check_${i}`;
            const result = context.fileCheckResults[checkId];
            if (result && result.exists) {
              issues.push({
                file: item.file,
                title: `Fix ${item.file}`,
              });
            }
          });
          return issues;
        },
        commentsToCreate: ({ context }) => {
          const comments = [];
          context.failingFiles.forEach((item, i) => {
            const checkId = `check_${i}`;
            const result = context.fileCheckResults[checkId];
            if (result && !result.exists) {
              comments.push({
                file: item.file,
              });
            }
          });
          return comments;
        },
      }),
      always: {
        target: 'performActions',
      },
    },

    performActions: {
      entry: enqueueActions(({ context, enqueue }) => {
        // Create all issues
        context.issuesToCreate.forEach((issue, i) => {
          enqueue(
            toolCall(
              'github.issue_write',
              {
                method: 'create',
                owner: 'acme',
                repo: 'widgets',
                title: issue.title,
              },
              { id: `issue_${i}` }
            )
          );
        });

        // Create all comments
        context.commentsToCreate.forEach((comment, i) => {
          const commentBody = `Missing file reported by failing check: ${comment.file}`;
          enqueue(
            toolCall(
              'github.add_issue_comment',
              {
                owner: 'acme',
                repo: 'widgets',
                issue_number: 139,
                body: commentBody,
              },
              { id: `comment_${i}` }
            )
          );
        });
      }),
      on: {
        TOOL_RESULT: {
          actions: assign({
            processedCount: ({ context }) => context.processedCount + 1,
          }),
        },
        TOOL_DENIED: {
          actions: assign({
            processedCount: ({ context }) => context.processedCount + 1,
          }),
        },
        TOOL_ERROR: {
          actions: assign({
            processedCount: ({ context }) => context.processedCount + 1,
          }),
        },
      },
      always: {
        guard: ({ context }) =>
          context.processedCount ===
          context.issuesToCreate.length + context.commentsToCreate.length,
        target: 'done',
      },
    },

    error: {
      type: 'final',
    },

    done: {
      type: 'final',
    },
  },
  output: ({ context }) => ({
    failingFiles: context.failingFiles,
    issuesToCreate: context.issuesToCreate,
    commentsToCreate: context.commentsToCreate,
  }),
});

