import { setup, assign, enqueueActions } from 'xstate';
import { toolCall, whenCall } from '@astral-mcp/tools';

interface Context {
  vipEmails: string[];
  database: string;
  collection: string;
  connectionId: string;
  toUpdate: string[];
  toAddToMissing: string[];
  updateResults: Record<string, any>;
  missingCheckResults: Record<string, any>;
  writeResult: any;
  error: string | null;
}

export default setup({}).createMachine({
  id: 'vipProcessing',
  context: (): Context => ({
    vipEmails: [],
    database: 'shop',
    collection: 'customers',
    connectionId: 'preconfigured',
    toUpdate: [],
    toAddToMissing: [],
    updateResults: {},
    missingCheckResults: {},
    writeResult: null,
    error: null,
  }),
  initial: 'readVipFile',
  states: {
    readVipFile: {
      entry: toolCall('fs.read_file', () => ({ path: 'notes/vip.txt' })),
      on: {
        TOOL_RESULT: {
          target: 'parseVips',
          actions: assign({
            vipEmails: ({ event }) => {
              const content = (event.result as any).content || event.result;
              return content
                .split('\n')
                .map((line: string) => line.trim())
                .filter((line: string) => line.length > 0);
            },
          }),
        },
        TOOL_ERROR: {
          target: 'failed',
          actions: assign({ error: ({ event }) => `Failed to read vip.txt: ${(event.error as any).message}` }),
        },
      },
    },
    parseVips: {
      always: {
        target: 'checkCustomers',
      },
    },
    checkCustomers: {
      entry: enqueueActions(({ context, enqueue }) => {
        context.vipEmails.forEach((email, i) => {
          enqueue(
            toolCall(
              'mongo.find',
              {
                connectionId: context.connectionId,
                database: context.database,
                collection: context.collection,
                filter: { email: email },
              },
              { id: `check_${i}` }
            )
          );
        });
      }),
      on: {
        TOOL_RESULT: {
          actions: assign({
            missingCheckResults: ({ context, event }) => ({
              ...context.missingCheckResults,
              [event.callId]: event.result,
            }),
          }),
        },
        TOOL_ERROR: {
          actions: assign({
            missingCheckResults: ({ context, event }) => ({
              ...context.missingCheckResults,
              [event.callId]: { error: true, message: (event.error as any).message },
            }),
          }),
        },
      },
      always: {
        guard: ({ context }) => {
          const expectedCount = context.vipEmails.length;
          const receivedCount = Object.keys(context.missingCheckResults).length;
          return receivedCount === expectedCount;
        },
        target: 'categorizeEmails',
      },
    },
    categorizeEmails: {
      always: {
        target: 'processUpdates',
        actions: assign({
          toUpdate: ({ context }) => {
            const updates: string[] = [];
            context.vipEmails.forEach((email, i) => {
              const result = context.missingCheckResults[`check_${i}`];
              if (result && (result as any).documents && (result as any).documents.length > 0) {
                updates.push(email);
              }
            });
            return updates;
          },
          toAddToMissing: ({ context }) => {
            const missing: string[] = [];
            context.vipEmails.forEach((email, i) => {
              const result = context.missingCheckResults[`check_${i}`];
              if (!result || !(result as any).documents || (result as any).documents.length === 0) {
                missing.push(email);
              }
            });
            return missing;
          },
        }),
      },
    },
    processUpdates: {
      entry: enqueueActions(({ context, enqueue }) => {
        context.toUpdate.forEach((email, i) => {
          enqueue(
            toolCall(
              'mongo.update-many',
              {
                connectionId: context.connectionId,
                database: context.database,
                collection: context.collection,
                filter: { email: email },
                update: { $set: { tier: 'gold' } },
              },
              { id: `update_${i}` }
            )
          );
        });
      }),
      on: {
        TOOL_RESULT: {
          actions: assign({
            updateResults: ({ context, event }) => ({
              ...context.updateResults,
              [event.callId]: event.result,
            }),
          }),
        },
        TOOL_DENIED: {
          actions: assign({
            updateResults: ({ context, event }) => ({
              ...context.updateResults,
              [event.callId]: { denied: true },
            }),
          }),
        },
        TOOL_ERROR: {
          actions: assign({
            updateResults: ({ context, event }) => ({
              ...context.updateResults,
              [event.callId]: { error: true },
            }),
          }),
        },
      },
      always: {
        guard: ({ context }) => {
          const expectedCount = context.toUpdate.length;
          if (expectedCount === 0) return true;
          const receivedCount = Object.keys(context.updateResults).length;
          return receivedCount === expectedCount;
        },
        target: 'writeMissingVips',
      },
    },
    writeMissingVips: {
      entry: toolCall('fs.write_file', ({ context }) => ({
        path: 'notes/missing-vips.txt',
        content: context.toAddToMissing.join('\n') + (context.toAddToMissing.length > 0 ? '\n' : ''),
      })),
      on: {
        TOOL_RESULT: {
          target: 'done',
          actions: assign({
            writeResult: ({ event }) => event.result,
          }),
        },
        TOOL_DENIED: {
          target: 'done',
          actions: assign({
            error: () => 'Write to missing-vips.txt was denied',
          }),
        },
        TOOL_ERROR: {
          target: 'done',
          actions: assign({
            error: ({ event }) => `Failed to write missing-vips.txt: ${(event.error as any).message}`,
          }),
        },
      },
    },
    done: {
      type: 'final',
    },
    failed: {
      type: 'final',
    },
  },
  output: ({ context }) => ({
    vipEmailsProcessed: context.vipEmails.length,
    updatedToGold: context.toUpdate.length,
    addedToMissing: context.toAddToMissing.length,
    missingVipEmails: context.toAddToMissing,
    error: context.error,
  }),
});
